impl AmountAggregate {
    fn add(self, amount: UInt) -> Self {
        match self {
            Self::Exact(value) => match value.0.checked_add(amount.0) {
                Some(sum) => Self::Exact(UInt(sum)), None => Self::AboveU128,
            },
            Self::AboveU128 => Self::AboveU128,
        }
    }
